          "question": "O projeto de um software usa uma abordagem híbrida. O gerente do projeto está confiante, uma vez que a equipe tem experiência nesse tipo de desenvolvimento. No final da primeira iteração ele organiza uma demonstração do sistema, convidando o dono do produto e outras partes interessadas importantes. Após a apresentação o patrocinador informa que um dos clientes que irá utilizar o software não está satisfeito, uma vez que suas necessidades não estão sendo atendidas. Satisfazer as necessidades desse usuário significa fazer mudanças radicais no sistema. Qual causa raiz mais provável que ocasionou o surgimento dessa questão?",
