          "question": "Durante uma retrospectiva, a equipe de um projeto ágil menciona que está tendo dificuldades em completar as tarefas planejadas dentro do sprint. Após uma análise, o gerente de projeto percebe que vários membros da equipe estão trabalhando em múltiplas tarefas simultaneamente.\nQual deve ser a melhor ação do gerente para melhorar a produtividade da equipe?",
          "options": [
            {
              "id": "A",
              "text": "Definir limites para o trabalho em andamento (Work In Progress - WIP) e incentivar a equipe a focar em menos tarefas ao mesmo tempo."
            },
            {
              "id": "B",
              "text": "Delegar as tarefas para os membros mais rápidos da equipe para acelerar as entregas."
            },
            {
              "id": "C",
              "text": "Aumentar o tempo de duração dos sprints para permitir que todas as tarefas sejam concluídas."
            },
            {
              "id": "D",
              "text": "Solicitar horas extras para que a equipe consiga concluir todas as tarefas planejadas."
            }
          ],
          "pairs": [],
          "answer": [
            "A"
          ],
          "required": 1,
          "area": "Fundamentos de Gerenciamento de Projetos",
