          "number": 75,
          "type": "single",
          "question": "Um gerente de projetos recentemente foi designado para uma equipe ágil altamente madura e eficiente. Durante uma revisão de sprint, ele sente algum descontentamento entre os membros da equipe em relação ao longo prazo para obter as licenças governamentais necessárias. A equipe é da opinião que isso atrasa as sprints e, portanto, as licenças deveriam ser deixadas para depois. No entanto, o Dono do Produto é de opinião que as licenças são necessárias para implementar o projeto conforme a legislação. O que o gerente do projeto deveria ter feito para evitar esse conflito?",
