              "number": 4,
              "type": "single",
              "question": "De acordo com os resultados divulgados pela equipe de vendas de uma empresa automotiva, os concorrentes estão reduzindo os preços dos produtos, fazendo com que a empresa perca participação de mercado. A empresa está no meio do projeto de um novo veículo e parece improvável que o produto obtenha o retorno previsto para o investimento. O que deve ser realizado pelo gerente do projeto para lidar com o cenário atual?",
