              "type": "single",
              "question": "Durante a fase de planejamento de um projeto de desenvolvimento de um novo produto, o gerente de projeto descobre que o cliente está sob pressão significativa para demonstrar à alta direção o retorno antecipado de seu investimento. O projeto tem vários resultados importantes distribuídos ao longo do seu ciclo de vida, mas é necessário identificar e obter resultados iniciais para sustentar o apoio e o financiamento das partes interessadas. O que o gerente de projeto deve fazer primeiro para garantir que o projeto agregue valor ao cliente o mais rápido possível?",
