              "number": 1,
              "type": "single",
              "question": "Caso: A adoção do painel de eficiência energética\nUma rede hospitalar está implantando um painel corporativo de eficiência energética para acompanhar consumo de energia, metas de redução, emissões evitadas e economia financeira por unidade. O projeto usa uma abordagem híbrida: a integração com medidores, sistemas prediais e relatórios financeiros segue marcos preditivos, enquanto os painéis de visualização e indicadores para gestores hospitalares são refinados em ciclos curtos com feedback dos usuários.\nO caso de negócios foi aprovado com base em três benefícios principais: reduzir em 12% o consumo de energia em 12 meses, melhorar a rastreabilidade dos indicadores ambientais e apoiar decisões de investimento em equipamentos mais eficientes. A diretoria também espera usar os dados consolidados em relatórios executivos e em comunicações institucionais sobre sustentabilidade.\nDurante a preparação do primeiro release, o gerente do projeto identifica quatro pontos relevantes:\nGovernança: Ainda não está claro quem aprova mudanças nos indicadores executivos, quem decide sobre conflitos entre unidades hospitalares e quais métricas serão reportadas ao comitê diretivo.\nAdoção: Algumas unidades temem que o painel seja usado para comparar publicamente seu desempenho e expor ineficiências operacionais antigas.\nRiscos: A integração com medidores de duas unidades críticas depende de um fornecedor externo que já atrasou entregas em projetos anteriores.\nAmbiente externo: Uma nova diretriz de sustentabilidade do setor hospitalar recomenda divulgar indicadores padronizados de consumo e emissões a partir do próximo ciclo anual de relatórios.\nO patrocinador quer manter a data do primeiro release, mas pede ao gerente do projeto uma recomendação para garantir que o painel produza valor real, seja adotado pelas unidades e possa sustentar decisões executivas.\n\nQual métrica melhor demonstra que o projeto está contribuindo para os benefícios definidos no caso de negócios?",
              "options": [
                {
                  "id": "A",
                  "text": "Quantidade de telas concluídas pela equipe de desenvolvimento em cada ciclo de trabalho."
                },
                {
                  "id": "B",
                  "text": "Percentual de unidades que acessaram o painel pelo menos uma vez após o release."
                },
                {
                  "id": "C",
                  "text": "Redução percentual do consumo de energia acompanhada por unidade hospitalar ao longo do tempo."
                },
                {
                  "id": "D",
                  "text": "Número de reuniões realizadas com gestores hospitalares durante o período de implantação."
                }
              ],
              "pairs": [],
              "answer": [
                "C"
              ],
              "required": 1,
              "area": "Fundamentos de Gerenciamento de Projetos",
              "domain": "Processo",
              "reference": "PMP - BOOK 8 — Fundamentos de gerenciamento de projetos e entrega de valor, sessão 8.",
              "explanation": "Resposta conforme o gabarito do material de origem.",
              "id": "fund-s8-q1",
              "source": "Sessão 8",
              "title": "Sessão 8",
              "session": 8
