                {
                  "id": "A",
                  "text": "Reportar o progresso em relação aos benefícios e resultados esperados."
                },
                {
                  "id": "B",
                  "text": "Reportar os pontos de história concluídos por sprint."
                },
                {
                  "id": "C",
                  "text": "Reportar o percentual de funcionalidades planejadas entregues."
                },
                {
                  "id": "D",
                  "text": "Reportar o número de defeitos abertos e riscos pendentes."
                }
