              "question": "Uma equipe iniciará o desenvolvimento de um novo produto em um mercado competitivo, com mudanças frequentes nas preferências dos clientes e aumento constante dos custos dos insumos. O gerente de projeto propõe usar uma abordagem incremental. Qual é a melhor justificativa para essa escolha?",
