              "question": "Durante uma sessão de estratégia, o Dono do Produto responsável por um novo dispositivo conversa com o presidente da divisão sobre uma oportunidade de mercado. A análise recente indica potencial de demanda, mas ainda há incerteza sobre quais funcionalidades realmente gerarão valor para clientes representativos do público-alvo. A liderança decide avançar com um produto mínimo viável (MVP).\nComo o MVP deve ser usado nesse contexto?",
