              "type": "single",
              "question": "Uma equipe Scrum precisa demonstrar um incremento ao final de cada iteração, mas percebe que frequentemente deixa a preparação da demonstração para a última hora. O Scrum Master quer ajudar a equipe a reservar tempo suficiente para preparar uma demonstração objetiva, baseada no incremento pronto. O que ele deve sugerir?",
