              "number": 1,
              "type": "single",
              "question": "Uma equipe nova em práticas ágeis identificou com o Dono do Produto as funcionalidades de maior valor. O gerente de projeto orienta a equipe a dividi-las em incrementos e entregá-las cedo. Por que essa orientação é adequada?",
