              "question": "Uma equipe multidisciplinar precisa disponibilizar rapidamente um aplicativo crítico de resposta a desastres. O prazo disponível é muito menor que o cronograma normalmente necessário, mas a solução precisa entregar funcionalidades essenciais com segurança suficiente para uso imediato. Que ação o gerente de projeto deve priorizar?",
