              "question": "Um gerente de projeto está apoiando uma equipe ágil que deseja maximizar o valor entregue ao cliente. Durante a revisão do backlog, a equipe identifica itens que consomem esforço, mas não estão vinculados a objetivos de negócio, critérios regulatórios, aprendizagem ou necessidades reais de usuários. O que o gerente de projeto deve recomendar eliminar primeiro?",
