              "question": "O gerente de um projeto ágil está iniciando a descoberta de requisitos com o dono do produto e algumas partes interessadas. Há muitas ideias, mas a equipe ainda não sabe quais itens devem entrar primeiro no backlog. Qual pergunta deve orientar inicialmente a conversa?",
