              "question": "Há uma discussão acalorada durante uma cerimônia de scrum entre o gerente do projeto e as principais partes interessadas. O gerente do projeto afirma que, durante os primeiros sprints, a equipe do projeto deve se concentrar em funcionalidades de menor valor e menos complexas. A parte interessada explica ao gerente do projeto que os recursos de alto valor devem ser priorizados para entregar o máximo de valor ao cliente o mais rápido possível. Quem está certo?",
